from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.gnb.gnb import CloudBts
from taf.config.cbts import CbtsProvider


class _OAMWrapper(object):
    def __init__(self, cu):
        self._cu = cu

    @property
    def username(self):
        return self._cu.oam_ssh_connection_details.username

    @username.setter
    def username(self, value):
        self._cu.oam_ssh_connection_details.username = value

    @property
    def addr(self):
        return self._cu.oam_ssh_connection_details.addr

    @addr.setter
    def addr(self, value):
        self._cu.oam_ssh_connection_details.addr = value

    @property
    def password(self):
        return self._cu.oam_ssh_connection_details.password

    @password.setter
    def password(self, value):
        self._cu.oam_ssh_connection_details.password = value


class _HeatWrapper(object):
    def __init__(self, cloudbts, old_cbts):
        self._cloudbts = cloudbts
        self._bts = _BTSWrapper(self._cloudbts, old_cbts=old_cbts)
        self._net = _NetWrapper(self._cloudbts, old_cbts=old_cbts)

    @property
    def bts(self):
        return self._bts

    @property
    def net(self):
        return self._net


class _BTSWrapper(object):
    def __init__(self, cloudbts, old_cbts):
        self._cloud_deployment = cloudbts.cloud_deployment
        self._old_cbts = old_cbts

    @property
    def dict(self):
        return self._cloud_deployment.vnfs[0].configuration_data

    @property
    def image(self):
        return self.dict['parameters']['image']

    @image.setter
    def image(self, value):
        self._old_cbts.heat.bts.image = value
        self._cloud_deployment.vnfs[0].configuration_data['parameters']['image'] = value

    @property
    def image_name(self):
        return self.dict['parameters']['image_name']

    @property
    def oam_ip(self):
        return self.dict['parameters']['oam_ip']

    @oam_ip.setter
    def oam_ip(self, value):
        self._old_cbts.heat.bts.oam_ip = value
        self._cloud_deployment.vnfs[0].configuration_data['parameters']['oam_ip'] = value

    @property
    def oam_network(self):
        return self.dict['parameters']['oam_network']

    @oam_network.setter
    def oam_network(self, value):
        self._old_cbts.heat.bts.oam_network = value
        self._cloud_deployment.vnfs[0].configuration_data['parameters']['oam_network'] = value

    @property
    def external_networks(self):
        return self.dict['parameters']['external_networks']

    @external_networks.setter
    def external_networks(self, ext_nets):
        self._old_cbts.heat.bts.external_networks = ext_nets
        self.dict['parameters']['external_networks'] = ext_nets


class _NetWrapper(object):
    def __init__(self, cloudbts, old_cbts):
        self._cloud_deployment = cloudbts.cloud_deployment
        self._old_cbts = old_cbts

    @property
    def dict(self):
        return self._cloud_deployment.networks[0].configuration_data


class _CBTSWrapper(ListAbstractionsWrapper):
    """
    _CBTSWrapper instance is an object containing two wrapper objects.
    """
    def __init__(self, tl_config):
        super(_CBTSWrapper, self).__init__(tl_config)
        # We use cloudbts from gnbs (not from tl.cloud_hostings[0], because we
        # need CU object, which is accessible only from particular gnb object)
        self._cloudbts = self.get_instance(CloudBts, self.tl_config.gnbs)
        if self._cloudbts is not None:
            self._oam = _OAMWrapper(cu=self._cloudbts.cu)

    def _load_heat_templates_data(self):
        if self._cloudbts is not None:

            cbts = self._load_old_cbts()
            vnf = self._cloudbts.cloud_deployment.vnfs[0]
            net = self._cloudbts.cloud_deployment.networks[0]

            self._initialize_configuration_data(cbts, net, vnf)

            self._heat = _HeatWrapper(cloudbts=self._cloudbts, old_cbts=cbts)
            self._heat.net.network_opts = cbts.heat.net.network_opts
            self._heat.bts.vnf_name = self.vnf_name

    def _initialize_configuration_data(self, cbts, net, vnf):
        # If somebody passed configuration data or assigned it to something,
        # then do not change it
        if vnf.configuration_data is None:
            vnf.configuration_data = cbts.heat.bts.dict
        if net.configuration_data is None:
            net.configuration_data = cbts.heat.net.dict

    def _load_old_cbts(self):
        cbts = CbtsProvider(net_yaml=self.net_yaml,
                            net_env=self._net_env(),
                            bts_yaml=self.bts_yaml,
                            bts_env=self._bts_env(),
                            flavors_yaml=self.flavors_yaml,
                            ).read_from_files(self.cfg_dir)
        return cbts

    def _cloud_deployment(self):
        return self._cloudbts.cloud_deployment

    def _bts_env(self):
        return self._cloud_deployment().vnfs[0].env_files[0]

    def _net_env(self):
        return self._cloud_deployment().networks[0].env_files[0]

    @property
    def oam(self):
        return self._oam

    @property
    def heat(self):
        self._load_heat_templates_data()
        return self._heat

    @property
    def vnf_name(self):
        return self._cloudbts.vnf_name

    @property
    def vnf_prefix(self):
        return self._cloud_deployment().flavors[0].default_vnf_prefix

    @property
    def bts_name(self):
        return self._cloud_deployment().vnfs[0].name

    @property
    def net_name(self):
        return self._cloud_deployment().networks[0].name

    @property
    def cfg_dir(self):
        return self._cloud_deployment().default_cfg_dir

    @property
    def flavor_name(self):
        return self._cloud_deployment().flavors[0].name

    @property
    def bts_yaml(self):
        return self._cloud_deployment().vnfs[0].yaml_file

    @property
    def net_yaml(self):
        return self._cloud_deployment().networks[0].yaml_file

    @property
    def flavors_yaml(self):
        return self._cloud_deployment().flavors[0].yaml_file

    @property
    def resource_registry(self):
        return self._cloud_deployment().vnfs[0].resource_registry

    @resource_registry.setter
    def resource_registry(self, value):
        self._cloud_deployment().vnfs[0].resource_registry = value
